/**
 * Daliesk command-deck mirror: token-protected writes.
 *
 * The container that runs the harness accepts no inbound connections, so it
 * pushes the local feed's snapshots and run events here and the public `feed`
 * function serves them. The first `POST /bootstrap` fixes the token (trust on
 * first use, stored as a SHA-256 digest); every later request must carry that
 * token in `x-daliesk-token`. Every write body is a JSON envelope
 * `{ gz: <base64 of gzip(JSON)> }`: code-safety findings quote injection and
 * traversal strings, which the web application firewall in front of this
 * project rejects when it can read them. Writes use the service role from the
 * function's own environment; no key appears in this source.
 */
const SUPABASE_URL = Deno.env.get('SUPABASE_URL') ?? ''
const SERVICE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
const REST = `${SUPABASE_URL}/rest/v1`
const STORAGE = `${SUPABASE_URL}/storage/v1/object`
const BUCKET = 'deck'
const AUTH = { apikey: SERVICE_KEY, Authorization: `Bearer ${SERVICE_KEY}` }
const JSON_HEADERS = { ...AUTH, 'Content-Type': 'application/json' }

function json(status: number, body: unknown): Response {
  return new Response(JSON.stringify(body), { status, headers: { 'content-type': 'application/json' } })
}

async function sha256Hex(text: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text))
  return Array.from(new Uint8Array(digest), byte => byte.toString(16).padStart(2, '0')).join('')
}

async function storedTokenHash(): Promise<string | undefined> {
  const res = await fetch(`${REST}/feed_config?key=eq.ingest_token_hash&select=value`, { headers: AUTH })
  if (!res.ok) throw new Error(`feed_config read answered ${res.status}`)
  const rows = await res.json() as { value: string }[]
  return rows[0]?.value
}

/** The route below the function name, with `/functions/v1/ingest` stripped when the gateway leaves it in. */
function routeOf(url: URL): string {
  const path = url.pathname.replace(/^\/functions\/v1/, '').replace(/^\/ingest/, '')
  return path === '' ? '/' : path
}

/** Bytes of a base64 string. */
function fromBase64(text: string): Uint8Array {
  const binary = atob(text)
  const bytes = new Uint8Array(binary.length)
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i)
  return bytes
}

/** Gunzip bytes. */
async function gunzip(bytes: Uint8Array): Promise<Uint8Array> {
  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))
  return new Uint8Array(await new Response(stream).arrayBuffer())
}

/** The request's payload: the `{ gz }` envelope unpacked, or the plain JSON body. */
async function payloadOf(req: Request): Promise<Record<string, unknown>> {
  const raw = await req.json() as Record<string, unknown>
  if (typeof raw.gz !== 'string') return raw
  const text = new TextDecoder().decode(await gunzip(fromBase64(raw.gz)))
  return JSON.parse(text) as Record<string, unknown>
}

async function rest(method: string, path: string, body?: unknown, prefer?: string): Promise<Response> {
  const res = await fetch(`${REST}${path}`, {
    method,
    headers: { ...JSON_HEADERS, ...(prefer === undefined ? {} : { Prefer: prefer }) },
    ...(body === undefined ? {} : { body: JSON.stringify(body) }),
  })
  if (!res.ok) throw new Error(`${method} ${path} answered ${res.status}: ${(await res.text()).slice(0, 300)}`)
  return res
}

interface MirrorEvent { sessionId?: unknown; seq?: unknown; [key: string]: unknown }

Deno.serve(async (req: Request) => {
  const url = new URL(req.url)
  const route = routeOf(url)
  const token = req.headers.get('x-daliesk-token') ?? ''
  if (token.length < 32) return json(401, { error: 'x-daliesk-token required' })
  try {
    const hash = await sha256Hex(token)
    const stored = await storedTokenHash()
    if (route === '/bootstrap' && req.method === 'POST') {
      if (stored !== undefined) return json(409, { error: 'already bootstrapped' })
      await rest('POST', '/feed_config', { key: 'ingest_token_hash', value: hash }, 'return=minimal')
      return json(201, { ok: true })
    }
    if (stored === undefined || stored !== hash) return json(403, { error: 'bad token' })

    if (route === '/json' && req.method === 'POST') {
      const { path, body } = await payloadOf(req)
      if (typeof path !== 'string' || !path.startsWith('/') || body === undefined) return json(400, { error: 'path and body required' })
      await rest('POST', '/feed_json?on_conflict=path', { path, body, updated_at: new Date().toISOString() }, 'resolution=merge-duplicates,return=minimal')
      return json(200, { ok: true })
    }
    if (route === '/events' && req.method === 'POST') {
      const { runId, events } = await payloadOf(req)
      if (typeof runId !== 'string' || !Array.isArray(events)) return json(400, { error: 'runId and events required' })
      const rows = (events as MirrorEvent[]).map(event => ({
        run_id: runId,
        session_id: typeof event.sessionId === 'string' ? event.sessionId : '',
        seq: typeof event.seq === 'number' ? Math.trunc(event.seq) : 0,
        body: event,
      }))
      if (rows.length > 0) await rest('POST', '/feed_events?on_conflict=run_id,session_id,seq', rows, 'resolution=ignore-duplicates,return=minimal')
      return json(200, { ok: true, accepted: rows.length })
    }
    if (route === '/requests' && req.method === 'GET') {
      const res = await rest('GET', '/feed_requests?claimed_at=is.null&order=id.asc&select=id,target,model,created_at')
      return json(200, await res.json())
    }
    const claim = /^\/requests\/(\d+)$/.exec(route)
    if (claim !== null && req.method === 'POST') {
      const { runId, error } = await payloadOf(req)
      await rest('PATCH', `/feed_requests?id=eq.${claim[1]}`, {
        claimed_at: new Date().toISOString(),
        run_id: typeof runId === 'string' ? runId : null,
        error: typeof error === 'string' ? error : null,
      }, 'return=minimal')
      return json(200, { ok: true })
    }
    if (route === '/upload' && req.method === 'POST') {
      const { path, cache, contentType, b64 } = await payloadOf(req)
      if (typeof path !== 'string' || path === '' || path.includes('..') || path.startsWith('/') || typeof b64 !== 'string') {
        return json(400, { error: 'a relative path and b64 content are required' })
      }
      const key = path.split('/').map(encodeURIComponent).join('/')
      const res = await fetch(`${STORAGE}/${BUCKET}/${key}`, {
        method: 'POST',
        headers: {
          ...AUTH,
          'content-type': typeof contentType === 'string' ? contentType : 'application/octet-stream',
          'cache-control': typeof cache === 'string' ? cache : 'max-age=60',
          'x-upsert': 'true',
        },
        body: fromBase64(b64),
      })
      const detail = (await res.text()).slice(0, 300)
      return json(res.ok ? 200 : 502, { ok: res.ok, status: res.status, detail })
    }
    if (route === '/reset' && req.method === 'POST') {
      await rest('DELETE', '/feed_events?id=gt.0', undefined, 'return=minimal')
      await rest('DELETE', '/feed_json?path=neq.', undefined, 'return=minimal')
      return json(200, { ok: true })
    }
    return json(404, { error: `no route for ${req.method} ${route}` })
  } catch (error) {
    return json(500, { error: error instanceof Error ? error.message : String(error) })
  }
})
/**
 * Daliesk command-deck mirror: the public read side of the feed.
 *
 * Serves the feed contract the deck reads — `GET /roster`, `GET /runs`,
 * `GET /programs`, `GET /safety/:id`, and the Server-Sent Events stream `GET /runs/:id/events` —
 * from the rows the `ingest` function stores, and turns `POST /safety` into a
 * request the pushing container claims and answers with the run id it
 * started. One event stream stays open for at most STREAM_MS, under the
 * runtime's wall-clock limit; the browser's EventSource reconnects with the
 * last row id it saw and the stream resumes from there.
 */
const SUPABASE_URL = Deno.env.get('SUPABASE_URL') ?? ''
const SERVICE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
const REST = `${SUPABASE_URL}/rest/v1`
const AUTH = { apikey: SERVICE_KEY, Authorization: `Bearer ${SERVICE_KEY}` }
const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Last-Event-ID',
}
const STREAM_MS = 140_000
const POLL_MS = 500
const PING_MS = 15_000
const PAGE = 2000
const REQUEST_WAIT_MS = 25_000

function json(status: number, body: unknown): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...CORS, 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' },
  })
}

/** The route below the function name, with `/functions/v1/feed` stripped when the gateway leaves it in. */
function routeOf(url: URL): string {
  const path = url.pathname.replace(/^\/functions\/v1/, '').replace(/^\/feed/, '')
  return path === '' ? '/' : path
}

async function restGet<T>(path: string): Promise<T> {
  const res = await fetch(`${REST}${path}`, { headers: AUTH })
  if (!res.ok) throw new Error(`GET ${path} answered ${res.status}`)
  return await res.json() as T
}

async function snapshot(path: string): Promise<unknown> {
  const rows = await restGet<{ body: unknown }[]>(`/feed_json?path=eq.${encodeURIComponent(path)}&select=body`)
  return rows[0]?.body
}

interface EventRow { id: number; body: unknown }

function eventsAfter(runId: string, after: number): Promise<EventRow[]> {
  return restGet<EventRow[]>(`/feed_events?run_id=eq.${encodeURIComponent(runId)}&id=gt.${after}&order=id.asc&limit=${PAGE}&select=id,body`)
}

function sleep(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms))
}

function streamEvents(runId: string, since: number): Response {
  const encoder = new TextEncoder()
  let open = true
  const stream = new ReadableStream<Uint8Array>({
    async start(controller) {
      const write = (text: string): void => {
        if (!open) return
        try {
          controller.enqueue(encoder.encode(text))
        } catch {
          open = false
        }
      }
      const started = Date.now()
      let after = since
      let pinged = Date.now()
      write(': daliesk mirror\n\n')
      while (open && Date.now() - started < STREAM_MS) {
        let rows: EventRow[] = []
        try {
          rows = await eventsAfter(runId, after)
        } catch {
          rows = []
        }
        for (const row of rows) {
          write(`id: ${row.id}\ndata: ${JSON.stringify(row.body)}\n\n`)
          after = row.id
        }
        if (rows.length === PAGE) continue
        if (Date.now() - pinged >= PING_MS) {
          write(': ping\n\n')
          pinged = Date.now()
        }
        await sleep(POLL_MS)
      }
      if (open) {
        open = false
        try {
          controller.close()
        } catch {
          // The client closed first.
        }
      }
    },
    cancel() {
      open = false
    },
  })
  return new Response(stream, {
    headers: { ...CORS, 'content-type': 'text/event-stream; charset=utf-8', 'cache-control': 'no-cache', connection: 'keep-alive' },
  })
}

async function startReview(req: Request): Promise<Response> {
  let body: { target?: unknown; model?: unknown }
  try {
    body = await req.json() as { target?: unknown; model?: unknown }
  } catch {
    return json(400, { error: 'JSON body required' })
  }
  if (typeof body.target !== 'string' || body.target.length === 0) return json(400, { error: 'POST /safety requires a non-empty "target"' })
  const model = typeof body.model === 'string' && body.model.length > 0 ? body.model : null
  const created = await fetch(`${REST}/feed_requests`, {
    method: 'POST',
    headers: { ...AUTH, 'content-type': 'application/json', Prefer: 'return=representation' },
    body: JSON.stringify({ target: body.target, model }),
  })
  if (!created.ok) return json(500, { error: `request not stored (${created.status})` })
  const [row] = await created.json() as { id: number }[]
  if (row === undefined) return json(500, { error: 'request not stored' })
  const deadline = Date.now() + REQUEST_WAIT_MS
  while (Date.now() < deadline) {
    await sleep(1000)
    const [state] = await restGet<{ run_id: string | null; error: string | null }[]>(`/feed_requests?id=eq.${row.id}&select=run_id,error`)
    if (state?.run_id) return json(202, { id: state.run_id })
    if (state?.error) return json(400, { error: state.error })
  }
  return json(504, { error: 'no harness claimed the request: the pushing container is not connected' })
}

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') return new Response(null, { status: 204, headers: CORS })
  const url = new URL(req.url)
  const route = routeOf(url)
  try {
    if (req.method === 'GET' && (route === '/roster' || route === '/runs' || route === '/programs')) {
      const body = await snapshot(route)
      return body === undefined ? json(503, { error: 'the mirror has not received this snapshot yet' }) : json(200, body)
    }
    const safety = /^\/safety\/([^/]+)$/.exec(route)
    if (req.method === 'GET' && safety !== null) {
      const body = await snapshot(`/safety/${decodeURIComponent(safety[1])}`)
      return body === undefined ? json(404, { error: `no code-safety run "${safety[1]}"` }) : json(200, body)
    }
    const events = /^\/runs\/([^/]+)\/events$/.exec(route)
    if (req.method === 'GET' && events !== null) {
      const since = Number(req.headers.get('last-event-id') ?? url.searchParams.get('since') ?? '0')
      return streamEvents(decodeURIComponent(events[1]), Number.isFinite(since) ? since : 0)
    }
    if (req.method === 'POST' && route === '/safety') return await startReview(req)
    if (req.method === 'GET' && route === '/health') {
      const rows = await restGet<{ path: string; updated_at: string }[]>('/feed_json?select=path,updated_at&order=updated_at.desc&limit=1')
      return json(200, { ok: true, lastSnapshot: rows[0] ?? null })
    }
    return json(404, { error: `no route for ${req.method} ${route}` })
  } catch (error) {
    return json(500, { error: error instanceof Error ? error.message : String(error) })
  }
})

#!/usr/bin/env node
/**
 * Mirrors the local harness feed into the hosted relay.
 *
 * Every JSON_EVERY_MS the pusher reads GET /runs, GET /roster, GET /programs
 * and, for each code-safety run, GET /safety/:id from the local feed and pushes each to the
 * relay's `ingest` function when its content changed. Every run on the local
 * feed is followed on its Server-Sent Events stream and the folded events are
 * forwarded in batches from one queue per run: running runs first, then
 * code-safety reviews, then the rest newest first, with IN_FLIGHT batches
 * sending at once. The relay ignores duplicates, so a restart re-sends safely,
 * and a batch the relay rejects is split down to the one event at fault, which
 * is dropped after MAX_REFUSALS so the rest keeps flowing. Every
 * REQUESTS_EVERY_MS the pusher claims review requests the hosted deck posted,
 * starts them on the local feed when the target is under TARGET_ROOT and the
 * model is a known short name, and reports the run id back.
 *
 * Every write body is the relay's envelope `{ gz: base64(gzip(JSON)) }`, so
 * the web application firewall in front of the relay never reads the
 * exploit-like strings a code-safety review quotes.
 *
 * Environment: LOCAL_FEED (default http://127.0.0.1:4711), INGEST_URL,
 * INGEST_TOKEN_FILE, TARGET_ROOT (default $HOME/targets).
 */
import { readFileSync } from 'node:fs'
import { get } from 'node:http'
import { createHash } from 'node:crypto'
import { resolve } from 'node:path'
import { gzipSync } from 'node:zlib'

const LOCAL = (process.env.LOCAL_FEED ?? 'http://127.0.0.1:4711').replace(/\/+$/, '')
const INGEST = (process.env.INGEST_URL ?? '').replace(/\/+$/, '')
const TOKEN = process.env.INGEST_TOKEN_FILE ? readFileSync(process.env.INGEST_TOKEN_FILE, 'utf8').trim() : ''
const TARGET_ROOT = resolve(process.env.TARGET_ROOT ?? `${process.env.HOME ?? '/root'}/targets`)
const MODELS = new Set(['sonnet', 'opus', 'haiku'])
const JSON_EVERY_MS = 3_000
const REQUESTS_EVERY_MS = 2_000
const FLUSH_EVERY_MS = 500
const BATCH = 500
const IN_FLIGHT = 4
const MAX_REFUSALS = 3

if (INGEST === '' || TOKEN === '') {
  console.error('pusher: INGEST_URL and INGEST_TOKEN_FILE are required')
  process.exit(2)
}

const log = (...parts) => console.log(new Date().toISOString(), ...parts)
const sleep = (ms) => new Promise((done) => setTimeout(done, ms))

function envelope(body) {
  return JSON.stringify({ gz: gzipSync(Buffer.from(JSON.stringify(body))).toString('base64') })
}

async function ingest(path, body, method = 'POST') {
  const res = await fetch(`${INGEST}${path}`, {
    method,
    headers: { 'x-daliesk-token': TOKEN, ...(body === undefined ? {} : { 'content-type': 'application/json' }) },
    ...(body === undefined ? {} : { body: envelope(body) }),
  })
  if (!res.ok) throw new Error(`${method} ${path} answered ${res.status}: ${(await res.text()).replace(/\s+/g, ' ').slice(0, 160)}`)
  return res
}

async function local(path, init) {
  const res = await fetch(`${LOCAL}${path}`, init)
  if (!res.ok) throw new Error(`local ${path} answered ${res.status}`)
  return res
}

const hashes = new Map()
async function pushIfChanged(path, body) {
  const hash = createHash('sha256').update(JSON.stringify(body)).digest('hex')
  if (hashes.get(path) === hash) return false
  await ingest('/json', { path, body })
  hashes.set(path, hash)
  return true
}

const stats = { snapshots: 0, events: 0, dropped: 0, requests: 0 }

/** One run's outgoing events and send state. */
class RunQueue {
  constructor(run) {
    this.runId = run.id
    this.events = []
    this.inflight = false
    this.batchSize = BATCH
    this.refusals = 0
    this.rank(run)
  }

  rank(run) {
    this.priority = [run.status === 'running' ? 0 : run.kind === 'code-safety' ? 1 : 2, -Date.parse(run.startedAt) || 0]
  }
}

const queues = new Map()

async function syncJson() {
  const runs = await (await local('/runs')).json()
  if (await pushIfChanged('/runs', runs)) stats.snapshots += 1
  if (await pushIfChanged('/roster', await (await local('/roster')).json())) stats.snapshots += 1
  if (await pushIfChanged('/programs', await (await local('/programs')).json())) stats.snapshots += 1
  for (const run of runs) {
    follow(run)
    if (run.kind !== 'code-safety') continue
    try {
      const detail = await (await local(`/safety/${encodeURIComponent(run.id)}`)).json()
      if (await pushIfChanged(`/safety/${run.id}`, detail)) stats.snapshots += 1
    } catch (error) {
      log('safety', run.id, error.message)
    }
  }
}

function follow(run) {
  const known = queues.get(run.id)
  if (known !== undefined) {
    known.rank(run)
    return
  }
  const queue = new RunQueue(run)
  queues.set(run.id, queue)
  void (async () => {
    for (;;) {
      try {
        await streamRun(queue)
      } catch (error) {
        log('stream', run.id, error.message)
      }
      await sleep(5_000)
    }
  })()
}

/**
 * Follow one run's Server-Sent Events on the local feed until the connection
 * ends. Uses `node:http` rather than `fetch`: a recorded run's stream is
 * silent after its replay, and the fetch client's body timeout would end it
 * every five minutes, replaying the whole run on each reconnect.
 */
function streamRun(queue) {
  return new Promise((_, reject) => {
    const request = get(`${LOCAL}/runs/${encodeURIComponent(queue.runId)}/events`, { headers: { accept: 'text/event-stream' } }, (res) => {
      if (res.statusCode !== 200) {
        res.resume()
        reject(new Error(`local events answered ${res.statusCode}`))
        return
      }
      res.setEncoding('utf8')
      let buffer = ''
      res.on('data', (chunk) => {
        buffer += chunk
        let end
        while ((end = buffer.indexOf('\n\n')) !== -1) {
          const frame = buffer.slice(0, end)
          buffer = buffer.slice(end + 2)
          const data = frame.split('\n').filter((line) => line.startsWith('data:')).map((line) => line.slice(5).trim()).join('\n')
          if (data === '') continue
          try {
            queue.events.push(JSON.parse(data))
          } catch {
            // A torn frame; the next one is whole.
          }
        }
      })
      res.on('end', () => reject(new Error('stream ended')))
      res.on('error', reject)
    })
    request.on('error', reject)
  })
}

function comparePriority(a, b) {
  return a.priority[0] - b.priority[0] || a.priority[1] - b.priority[1]
}

async function sendBatch(queue) {
  queue.inflight = true
  const batch = queue.events.splice(0, queue.batchSize)
  try {
    await ingest('/events', { runId: queue.runId, events: batch })
    stats.events += batch.length
    queue.batchSize = BATCH
    queue.refusals = 0
  } catch (error) {
    log('events', queue.runId, `${batch.length} event(s):`, error.message)
    if (batch.length > 1) {
      queue.batchSize = Math.max(1, Math.floor(batch.length / 2))
      queue.events.unshift(...batch)
    } else {
      queue.refusals += 1
      if (queue.refusals >= MAX_REFUSALS) {
        stats.dropped += 1
        log('dropped', queue.runId, `session ${batch[0]?.sessionId} seq ${batch[0]?.seq} after ${MAX_REFUSALS} refusals`)
        queue.refusals = 0
        queue.batchSize = BATCH
      } else {
        queue.events.unshift(...batch)
        await sleep(2_000)
      }
    }
  } finally {
    queue.inflight = false
  }
}

function flush() {
  const inflight = [...queues.values()].filter((queue) => queue.inflight).length
  const ready = [...queues.values()].filter((queue) => !queue.inflight && queue.events.length > 0).sort(comparePriority)
  for (const queue of ready.slice(0, Math.max(0, IN_FLIGHT - inflight))) void sendBatch(queue)
}

async function relayRequests() {
  const rows = await (await ingest('/requests', undefined, 'GET')).json()
  for (const row of rows) {
    const target = resolve(String(row.target ?? '').replace(/^~(?=\/|$)/, process.env.HOME ?? '/root'))
    const model = row.model ?? undefined
    let outcome
    if (!target.startsWith(`${TARGET_ROOT}/`)) outcome = { error: `target must be under ${TARGET_ROOT}` }
    else if (model !== undefined && !MODELS.has(model)) outcome = { error: 'model must be sonnet, opus or haiku' }
    else {
      try {
        const res = await fetch(`${LOCAL}/safety`, {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify(model === undefined ? { target } : { target, model }),
        })
        const body = await res.json()
        outcome = res.ok && typeof body.id === 'string' ? { runId: body.id } : { error: body.error ?? `local feed answered ${res.status}` }
      } catch (error) {
        outcome = { error: error.message }
      }
    }
    await ingest(`/requests/${row.id}`, outcome)
    stats.requests += 1
    log('request', row.id, row.target, JSON.stringify(outcome))
  }
}

function every(ms, task, name) {
  let busy = false
  setInterval(() => {
    if (busy) return
    busy = true
    Promise.resolve().then(task).catch((error) => log(name, error.message)).finally(() => { busy = false })
  }, ms)
}

log(`pusher: ${LOCAL} -> ${INGEST} (targets under ${TARGET_ROOT})`)
every(JSON_EVERY_MS, syncJson, 'sync')
every(FLUSH_EVERY_MS, flush, 'flush')
every(REQUESTS_EVERY_MS, relayRequests, 'requests')
setInterval(() => {
  const queued = [...queues.values()].reduce((sum, queue) => sum + queue.events.length, 0)
  log(`stats snapshots=${stats.snapshots} events=${stats.events} dropped=${stats.dropped} requests=${stats.requests} queued=${queued} runs=${queues.size}`)
