name: Deploy command deck

# Publishes the Command Deck's static export to this repository's GitHub
# Pages site through the `gh-pages` branch, which GitHub serves at
# https://lbjlincoln.github.io/deepseek-harness/. The page reads the mirror
# relay by default, so it is live while the operator's machine pushes to the
# relay and replays the committed fixtures otherwise. The branch holds one
# commit, the current export, and is replaced on every publish. The deck is
# the whole Pages site, so this deployment and the documentation workflow's
# replace each other: the documentation deploys from master, the deck from
# its branch.

on:
  push:
    branches: [claude/coding-agent-harness-u9l4gt]
    paths:
      - '.github/workflows/deck-pages.yml'
      - 'apps/command-deck/**'
      - 'pnpm-lock.yaml'
  workflow_dispatch:

concurrency:
  group: gh-pages
  cancel-in-progress: false

permissions:
  contents: write

env:
  NEXT_TELEMETRY_DISABLED: '1'

jobs:
  publish:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v6

      - uses: pnpm/action-setup@v4

      - uses: actions/setup-node@v6
        with:
          node-version: '22'
          cache: pnpm

      - name: Install the deck's dependencies
        run: pnpm install --frozen-lockfile --ignore-scripts --filter @deepseek-ai/dsh-command-deck

      - name: Build the static export
        env:
          DECK_STATIC: '1'
          # A project site lives under the repository's name.
          NEXT_PUBLIC_BASE_PATH: /${{ github.event.repository.name }}
          # The feed the published deck reads: the repository variable when set,
          # else the mirror relay the operator's container pushes to; a viewer
          # can still name another with `?feed=` on the page URL.
          NEXT_PUBLIC_FEED_URL: ${{ vars.DECK_FEED_URL || 'https://cnaxcqiuwibsswfjjpko.supabase.co/functions/v1/feed' }}
        run: pnpm --dir apps/command-deck run build

      - name: Keep the export's underscore directories out of Jekyll's hands
        run: touch apps/command-deck/out/.nojekyll

      - name: Publish the export as the gh-pages branch
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
        run: |
          cd apps/command-deck/out
          git init -q -b gh-pages
          git config user.name 'github-actions[bot]'
          git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
          git add -A
          git commit -q -m "deck: static export of ${GITHUB_SHA}"
          git push --force "https://x-access-token:${GITHUB_TOKEN}@github.com/${GITHUB_REPOSITORY}.git" HEAD:gh-pages
